args.command:
node --input-type=module -e "
import { normalizeKey } from './src/keys.js';
import { createCache } from './src/cache.js';
console.log('normalizeKey Alpha ->', JSON.stringify(normalizeKey('Alpha')));
console.log('normalizeKey  Beta  ->', JSON.stringify(normalizeKey('  Beta ')));
const c = createCache({ clock: { now: () => 0 } });
c.set('Alpha','A'); c.set('alpha','B');
console.log('size after two mixed-case sets:', c.size());
console.log('get Alpha:', c.get('Alpha'));
"

cat > /tmp/probe.mjs <<'EOF'
import { normalizeKey } from './src/keys.js';
import { createCache } from './src/cache.js';
console.log('normalizeKey Alpha ->', JSON.stringify(normalizeKey('Alpha')));
console.log('normalizeKey "  Beta " ->', JSON.stringify(normalizeKey('  Beta ')));
const c = createCache({ clock: { now: () => 0 } });
c.set('Alpha','A'); c.set('alpha','B');
console.log('size after two mixed-case sets:', c.size());
console.log('get Alpha:', c.get('Alpha'));
EOF
node /tmp/probe.mjs

